#!/usr/bin/env node
// ingest-hook.mjs —— 记账钩子：Claude Code 在会话停止（Stop）或收尾（SessionEnd）时调它。
// stdin 收事件 JSON（含 transcript_path 会话记录路径、cwd 会话工作目录）。
// 规矩：
//   ① 当前目录不是 OPC 项目（没有 .opc/）→ 静默退出 0——不骚扰无关会话；
//   ② 是 OPC 项目 → 转调 opc.mjs tokens-ingest 入账（经唯一命令行入口，
//     将来挂在入口上的版本预检等关卡对记账同样生效）；
//   ③ 入账失败 → stderr 白话报错、非零退出——出错不吞，账断了就要让人看见。

import { existsSync } from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

// opc.mjs 按本文件位置定位（scripts/hooks/ → scripts/），跟钩子从哪个目录被拉起无关。
const opcScript = fileURLToPath(new URL('../opc.mjs', import.meta.url));

// 读全 stdin（钩子事件 JSON 就从这来）。
const chunks = [];
for await (const chunk of process.stdin) chunks.push(chunk);
let event;
try {
  event = JSON.parse(Buffer.concat(chunks).toString('utf8'));
} catch {
  process.stderr.write('记账钩子没收到合法的事件 JSON，没法入账\n');
  process.exit(1);
}

// 作用域判断：按会话工作目录找 .opc/，找不到就静默走人（宪法：不骚扰无关会话）。
const cwd = typeof event.cwd === 'string' && event.cwd !== '' ? event.cwd : process.cwd();
if (!existsSync(path.join(cwd, '.opc'))) {
  process.exit(0);
}

// 到这一步就是 OPC 项目了：记录路径缺失属于异常，必须出声，不能装没事。
const transcript = event.transcript_path;
if (typeof transcript !== 'string' || transcript === '') {
  process.stderr.write('记账钩子的事件里没有 transcript_path（会话记录路径），没法入账\n');
  process.exit(1);
}

const r = spawnSync(process.execPath, [opcScript, 'tokens-ingest', '--transcript', transcript, '--dir', cwd], {
  encoding: 'utf8'
});
if (r.error) {
  process.stderr.write(`记账钩子拉不起 opc.mjs：${r.error.message}\n`);
  process.exit(1);
}
if (r.status !== 0) {
  process.stderr.write(`记账失败（退出码 ${r.status}）：${r.stderr}`);
  process.exit(1);
}
process.exit(0);

